function errorList(){
 const errors=[];for(const el of $('fact-form').querySelectorAll('[name]')){
  el.removeAttribute('aria-invalid');if(el.disabled)continue;if(el.type==='search')continue;const v=el.value.trim();let message='';
  if(el.required&&(el.type==='checkbox'?!el.checked:!v))message=`Complete ${labels.get(el.name)?.label.toLowerCase()||'this field'}.`;
  else if(v&&!el.checkValidity())message=`Check ${labels.get(el.name)?.label.toLowerCase()||'this field'}.`;
  else if(v&&el.type==='url'&&!/^https?:\/\//i.test(v))message='Enter a full website link beginning with https:// or http://.';
  else if(v&&el.type==='tel'&&!/^\+?[\d\s().-]{7,25}$/.test(v))message='Enter a valid phone number.';
  else if(v&&el.name.endsWith('.postcode')&&!(el.name.startsWith('owners.')&&state[el.name.match(/^owners\.\d+/)[0]+'.immigrationStatus']==='Not resident in the UK')&&!/^[A-Z]{1,2}\d[A-Z\d]?\s*\d[A-Z]{2}$/i.test(v))message='Enter a UK postcode.';
  if(message)errors.push({name:el.name,message});
 }
 for(let i=0;i<loanCount;i++){const p='loans.'+i;if($('f-'+p+'.term')&&Boolean(state[p+'.term'])!==Boolean(state[p+'.termUnit']))errors.push({name:p+'.term',message:'For a loan term, enter both the length and its unit, or leave both blank.'});}
 if($('fields').querySelector('.loan-types')&&state['questions.loans']==='yes'&&loanCount===0)errors.push({name:'loanTypes.'+loanCategories[0][0],message:'Select at least one existing-loan category and enter the facility details.'});
 if(step===2&&state['funding.repayment2']&&(state['funding.repayment2']===state['funding.repayment']||state['funding.repayment']==='I’m open to all options'))errors.push({name:'funding.repayment2',message:'Choose a different second repayment preference, or leave it blank.'});
 if(step===0&&/^(?:\d{8}|[A-Z]{2}\d{6})$/i.test(state['business.name']||''))errors.push({name:'business.name',message:'Choose your company from the matches, or enter its business name.'});
 if(step===1&&substep===0&&['Limited company','LLP'].includes(state['business.structure'])&&!/^(?:\d{8}|[A-Z]{2}\d{6})$/i.test(state['business.number']||''))errors.push({name:'business.number',message:'Enter an eight-character company number for the registered business.'});
 if(step===3){
  let total=0;for(let i=0;i<ownerCount;i++){
   const p=`owners.${i}`;total+=Number(state[p+'.ownership']||0);
   if($('f-'+p+'.since')&&needsHistory(i)){
    let covered=monthIndex(state[p+'.since']);const ranges=Array.from({length:previousCounts[i]},(_,j)=>({j,from:monthIndex(state[p+`.previous.${j}.from`]),to:monthIndex(state[p+`.previous.${j}.to`])})).sort((a,b)=>b.to-a.to);
    for(const r of ranges){if(!Number.isFinite(r.from)||!Number.isFinite(r.to)||r.from>=r.to||r.to>currentMonth){errors.push({name:p+`.previous.${r.j}.from`,message:`Person ${i+1}: check the previous address dates.`});continue;}if(r.to<covered||r.to>monthIndex(state[p+'.since'])){errors.push({name:p+`.previous.${r.j}.to`,message:`Person ${i+1}: address dates must cover the period up to the current address, without gaps.`});}else covered=Math.min(covered,r.from);}
    if(covered>currentMonth-36)errors.push({name:p+'.since',message:`Person ${i+1}: add enough address history to cover the last three years.`});
   }
  }if($('fields').querySelector('[name$=".ownership"]')&&total>100.001)errors.push({name:$('fields').querySelector('[name$=".ownership"]')?.name||'owners.0.ownership',message:'Combined ownership cannot exceed 100%.'});
 }
 if($('f-property.minimumTerm')&&state['property.minimumTerm']&&state['property.maximumTerm']&&Number(state['property.minimumTerm'])>Number(state['property.maximumTerm']))errors.push({name:'property.maximumTerm',message:'Maximum term must be at least the minimum term.'});
 if($('f-property.term')){const term=Number(state['property.term']),min=Number(state['property.minimumTerm']),max=Number(state['property.maximumTerm']);if((min&&term<min)||(max&&term>max))errors.push({name:'property.term',message:'Preferred term must be within your minimum and maximum terms.'});if(state['property.termUnit']==='Years'&&[term,min,max].some(x=>x>40))errors.push({name:'property.termUnit',message:'Enter a term of up to 40 years, or choose months.'});}
 for(const [occupied,total]of [['occupiedFlats','flats'],['occupiedShops','shops']])if($('f-property.'+occupied)&&Number(state['property.'+occupied])>Number(state['property.'+total]))errors.push({name:'property.'+occupied,message:'Let units cannot exceed the number of units entered.'});
 if($('f-property.flats')&&Number(state['property.flats'])+Number(state['property.shops'])+Number(state['property.otherUnits'])===0)errors.push({name:'property.flats',message:'Enter at least one property unit.'});
 return errors.filter(e=>currentControl($('f-'+e.name)));
}
