$('ff-reset').addEventListener('click',()=>$('reset-dialog').showModal());$('reset-cancel').addEventListener('click',()=>$('reset-dialog').close());
$('reset-confirm').addEventListener('click',()=>{appliedExplorer=null;pendingExplorer=null;declinedSignature=null;state={};labels.clear();step=0;substep=0;furthest=0;bankCount=1;emailVerified=false;applicationId=null;revision=0;ownerCount=1;loanCount=0;previousCounts=[1];finished=false;$('reset-dialog').close();render();});
// A page restored from browser history must not restore personal form entries.
window.addEventListener('pageshow',e=>{if(e.persisted){appliedExplorer=null;pendingExplorer=null;declinedSignature=null;state={};labels.clear();step=0;substep=0;furthest=0;bankCount=1;emailVerified=false;applicationId=null;revision=0;ownerCount=1;loanCount=0;previousCounts=[1];finished=false;render(false);}});
