function showExplorerSummary(){
 const node=$('ff-carried');node.hidden=!appliedExplorer;
 if(appliedExplorer)node.innerHTML='<strong>Your explorer answers are here.</strong><p>Funding amount, purpose, repayment preference, business structure, turnover and card-payment details have been carried across. You can check or change them as you go.</p>';
 $('ff-import-update').hidden=!pendingExplorer||finished;
 if(pendingExplorer)$('ff-import-description').textContent=`Use the latest funding target of ${displayValue('funding.amount',pendingExplorer.fields['funding.amount'])} for ${pendingExplorer.fields['funding.purpose'].toLowerCase()}? This replaces the funding, business structure and trading figures carried from the explorer. Your contact, address and owner details stay as entered. You will check the annual estimate again.`;
}
function applyExplorer(seed){
 Object.assign(state,seed.fields);if(seed.fields['property.interested']==='yes')state['funding.route']='property';state['financial.turnoverChecked']='';state['preview.accuracy']='';
 if(state['financial.cards']==='no')for(const key of ['financial.processor','financial.processorOther','financial.cardSales','financial.terminals','financial.locations'])state[key]='';
 if(state['funding.purpose']!=='Other business purpose')state['funding.otherPurpose']='';
 appliedExplorer=seed;pendingExplorer=null;declinedSignature=null;state['application.acceptance']='no';emailVerified=false;submitKey=crypto.randomUUID();
 if(step>=2)step=2;
 render(false);
}
export function offerExplorerDetails(seed){
 if(!seed||finished){render(false);return;}
 const hasStarted=Boolean(furthest>0||state['funding.amount']);
 if(!appliedExplorer&&!hasStarted){applyExplorer(seed);return;}
 pendingExplorer=seed.signature!==appliedExplorer?.signature&&seed.signature!==declinedSignature?seed:null;
 render(false);
}
$('ff-use-updated').addEventListener('click',()=>{if(pendingExplorer&&!finished){save();applyExplorer(pendingExplorer);$('step-title').focus();}});
$('ff-keep').addEventListener('click',()=>{declinedSignature=pendingExplorer?.signature;pendingExplorer=null;showExplorerSummary();});

export function setJourneyContext({mode='self',intent='application',agentCode=''}={}){
 if(agentCode)state['journey.agentCode']=agentCode;
 if(!applicationId&&furthest===0){state['journey.mode']=mode;state['journey.confirmation']=mode==='self'?'client':'';}
 if(state['journey.intent']!==intent){state['journey.intent']=intent;step=0;substep=0;}
}
$('fact-form').addEventListener('input',e=>{
 const name=e.target.dataset.providerSearch;if(!name)return;const select=$('f-'+name),selected=select.value,query=e.target.value.toLowerCase();const options=name==='financial.bank'?[...new Set([...commonAccountProviders,...registeredBanks])].sort((a,b)=>a.localeCompare(b)):cardProcessors;
 select.innerHTML='<option value="">Choose</option>'+options.filter(n=>n.toLowerCase().includes(query)||n===selected).map(n=>`<option value="${esc(n)}" ${n===selected?'selected':''}>${esc(n)}</option>`).join('')+`<option value="other" ${selected==='other'?'selected':''}>Other — enter the name</option>`;
});

export function offerFundingAmount(amount){
 if(!state['funding.amount']&&Number.isFinite(amount)&&amount>0&&amount<=1e9){state['funding.amount']=String(amount);render(false);}
}

