$('fact-form').addEventListener('input',e=>{if(e.target.name&&!e.target.name.startsWith('application.'))invalidate();if(e.target.name)clearFieldError(e.target);updateEquity();});
const firstContact=getLeadContact();for(const [key,v]of Object.entries({'applicant.fullName':firstContact.name,'applicant.email':firstContact.email,'applicant.phone':firstContact.phone,'business.name':firstContact.business}))if(v&&!state[key])state[key]=v;
if(location.hash==='#property'){state['property.interested']='yes';state['funding.route']='property';}
checkInvitation().then(result=>{if(result){invitationStatus=result;render(false);if(result.pending)showError('This team member’s link is not verified in the review version. No attribution has been saved.');}}).catch(()=>{invitationStatus={pending:true};showError('This team member’s invitation could not be checked. You can still start a direct enquiry.');});
if(!preview){$('ff-example').hidden=true;const notice=document.querySelector('[data-preview-only]');if(notice)notice.hidden=true;}
render(false);

$('fact-form').addEventListener('click',async e=>{if(e.target.id!=='ff-save-later'||busy)return;save();busy=true;e.target.disabled=true;try{await saveLive();await request('/resume/request',{applicationId,revision});showError('Your progress is saved. If your enquiry is active, a secure continuation email will be sent to your email address. Drafts remain available for 45 days from the start of your enquiry.');}catch(error){showError(error.message);}finally{busy=false;e.target.disabled=false;}});
function openSavedDraft(){resumeDraft().then(snapshot=>{if(!snapshot)return;state={...snapshot.fields,'application.acceptance':'no'};state['journey.mode']='self';state['journey.confirmation']='client';applicationId=snapshot.applicationId;revision=snapshot.revision;ownerCount=Math.max(1,Math.min(10,Number(snapshot.counts.owners)||1));loanCount=Math.max(0,Math.min(30,Number(snapshot.counts.loans)||0));bankCount=Math.max(1,Math.min(8,Number(snapshot.counts.banks)||1));previousCounts=Array.from({length:ownerCount},(_,i)=>Math.max(1,Math.min(10,Number(snapshot.counts.previousAddresses?.[i])||1)));emailVerified=false;finished=false;step=0;substep=0;furthest=0;submitKey=crypto.randomUUID();render();$('step-description').textContent='Your saved answers are here. Check each short section, then review and accept your terms.';}).catch(error=>showError(error.message));}
openSavedDraft();window.addEventListener('hashchange',()=>{if(/^#(resume|review)=/.test(location.hash))openSavedDraft();});

