setFactFindCallback({active:()=>$('fact-form').getClientRects().length>0&&!finished,submit:async({contact,preferredTime,token,idempotencyKey})=>{
 if(busy)throw new Error('Your form is saving. Please try your callback request in a moment.');busy=true;
 try{save();invalidate();state['applicant.fullName']=contact.name;state['business.name']=contact.business;state['applicant.email']=contact.email;state['applicant.phone']=contact.phone;for(const [name,value]of Object.entries({'applicant.fullName':contact.name,'business.name':contact.business,'applicant.email':contact.email,'applicant.phone':contact.phone})){const el=$('f-'+name);if(el)el.value=value;}const r=await request('/callback/request',{applicationId,revision,contact,preferredTime,fields:cleanFields(),section:steps[step][0],block:blocks(step)[substep]?.title,counts:{owners:ownerCount,loans:loanCount,banks:bankCount,previousAddresses:previousCounts},invitationRef:invitationRef(),proposedAgentCode:state['journey.agentCode']||'',assisted:state['journey.mode']!=='self',contactWordingVersion:'2026-09-24-enquiry-1',termsVersion:'2026-09-24-website-1',turnstileToken:token},idempotencyKey);
 if(typeof r.applicationId!=='string'||!Number.isInteger(r.revision)||r.revision<revision||r.callbackSaved!==true)throw new Error('Your callback request could not be confirmed. Please try again.');applicationId=r.applicationId;revision=r.revision;return r;}finally{busy=false;}
}});
